import { gridDisk, latLngToCell } from 'h3-js'

export const H3_ASSIGNMENT_RESOLUTION = 9

export interface GeoPoint {
  latitude: number
  longitude: number
}

function assertPoint(point: GeoPoint) {
  if (!Number.isFinite(point.latitude) || !Number.isFinite(point.longitude)) {
    throw new Error('A valid latitude and longitude are required')
  }
  if (point.latitude < -90 || point.latitude > 90 || point.longitude < -180 || point.longitude > 180) {
    throw new Error('Latitude or longitude is out of range')
  }
}

export function h3CellForPoint(point: GeoPoint, resolution = H3_ASSIGNMENT_RESOLUTION): string {
  assertPoint(point)
  return latLngToCell(point.latitude, point.longitude, resolution)
}

export function h3DiskForPoint(point: GeoPoint, ring: number): string[] {
  if (!Number.isInteger(ring) || ring < 0) throw new Error('The H3 ring must be a non-negative integer')
  return gridDisk(h3CellForPoint(point), ring)
}
